UPDATE REPAIR_REQUESTS r
   SET r.RECEIPT_STATUS = #{toStatus}

     , r.VISIT_CONFIRMED_AT = SYSTIMESTAMP

 WHERE r.REPAIR_NO      = #{repairNo}
   AND r.RECEIPT_STATUS = #{fromStatus}
   AND EXISTS (
           SELECT 1 FROM ESTIMATES e
            WHERE e.REPAIR_NO        = r.REPAIR_NO
              AND e.FIXER_ID         = #{fixerId}
              AND e.ESTIMATES_STATUS = 'ACCEPTED'
       )
